   299    template <typename T>
   300    inline bool check_array (const T *base, unsigned int len, unsigned int record_size = T::static_size) const
   301    {
   302      const char *p = (const char *) base;
   303      bool overflows = hb_unsigned_mul_overflows (len, record_size);
   304      unsigned int array_size = record_size * len;
   305      bool ok = !overflows && this->check_range (base, array_size);
   306
   307      DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   308         "check_array [%p..%p] (%d*%d=%d bytes) in [%p..%p] -> %s",
   309         p, p + (record_size * len), record_size, len, (unsigned int) array_size,
   310         this->start, this->end,
   311         overflows ? "OVERFLOWS" : ok ? "OK" : "OUT-OF-RANGE");
   312
   313      return likely (ok);
   314    }
